+
+            // add cell to cellArray
+            if (topoElem.size() == mapCcxTypeNodes[info[0]]) {
+                fillCell(cellArray, topoElem, vtkType, info[0]);
+                topoElem.clear();
+                mapElem[elem] = elemID++;
