+    numComps = entityNames.size();
+
+    // enter in node values block
+    std::string code1 = " -1";
+    std::string code2 = " -2";
+    int node;
+    double value;
+    std::vector<double> vecValues;
+    std::vector<double> scaValues;
+    std::vector<int> nodes;
+    int countNodes = 0;
