+void addCell(vtkSmartPointer<vtkCellArray>& cellArray, const std::vector<int>& topoElem)
+{
+    vtkSmartPointer<T> cell = vtkSmartPointer<T>::New();
+    cell->GetPointIds()->SetNumberOfIds(topoElem.size());
