+// give position of first non-blank character of string_view
+size_t getFirstNotBlankPos(const std::string_view& view)
+{
+    size_t pos = view.find_first_not_of(" ");
+    if (pos == std::string_view::npos) {
+        pos = 0;
+    }
+
+    return pos;
+}
