+// get number of digits from format indicator
+int getDigits(int indicator)
+{
+    int digits = 0;
+    if (indicator == 0) {
+        // short
+        digits = 5;
+    }
+    else if (indicator == 1) {
+        // long
+        digits = 10;
+    }
+
+    return digits;
+}
